/** EnglishEnglishEnglishEnglishEnglishEnglishEnglish：EnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglish（es/ja/fr/de/ru EnglishEnglishEnglishEnglishEnglishEnglish），EnglishEnglishEnglishEnglishEnglishEnglish。
 *  EnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglish hud.js EnglishEnglishEnglishEnglish（source EnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglishEnglish）。 */
export function factsFor(id) {
  const table = FACTS_EN;
  const arr = table[id] ?? table._generic;
  return arr.map((f) => (typeof f === 'string' ? f : f.text));
}
